              let decodeP1 = (d_txt.bh_decode_p1 || "Your emotional mind (the Moon) is placed in the sign of <strong>{sign}</strong>. This gives your inner emotional world a <strong>{element}</strong> nature.").replace('{sign}', moonSignName).replace('{element}', moonElement);
              let meansP1 = (d_txt.bh_means_p1 || "Individually, this placement shapes how you give and receive love. You only need to worry about Bhakoot Dosha when comparing your chart for marriage. For instance, if your partner's Moon sign is exactly 6 or 8 signs away from {sign} (known as Shadashtaka), it can create friction—but even that has powerful astrological cancellations!").replace('{sign}', moonSignName);
              let analysisP = (d_txt.bh_analysis_p || "Bhakoot Dosha is <strong>NOT APPLICABLE</strong> to individual charts. Your emotional baseline is rooted in the sign of <strong>{sign}</strong>.").replace('{sign}', moonSignName);

              bhakootDetailsHtml = `
                  <h4 style="color: #1F2937; margin-top: 12px; margin-bottom: 4px; font-size: 1rem;">${t_what}</h4>
                  <p style="line-height: 1.6;">${d_txt.bh_what_p1 || "Let's decode this and bust another massive astrology myth! If you are searching for \"Bhakoot Dosha\" in your individual chart, stop worrying. <strong>Bhakoot Dosha is impossible for a single person to have!</strong> It is strictly a matchmaking (Kundali Milan) parameter used to check emotional and psychological compatibility between two partners based on the distance between their Moon signs."}</p>

                  <h4 style="color: #1F2937; margin-top: 16px; margin-bottom: 4px; font-size: 1rem;">${t_decode}</h4>
                  <p style="line-height: 1.6;">${decodeP1}</p>

                  <h4 style="color: #1F2937; margin-top: 16px; margin-bottom: 4px; font-size: 1rem;">${t_means}</h4>
                  <p style="line-height: 1.6;">${meansP1}</p>

                  <div style="background: rgba(0,0,0,0.02); border: 1px solid rgba(0,0,0,0.08); padding: 16px; border-radius: 12px; margin-top: 24px; margin-bottom: 16px;">
                      <h4 style="margin-top: 0; color: var(--accent); font-size: 1rem; margin-bottom: 8px;">${t_analysis}</h4>
                      <p style="margin:0; line-height: 1.6;">${analysisP}</p>
                  </div>

                  <h4 style="color: #1f2937; margin-bottom: 8px; font-size: 1rem;">${(d_txt.bh_insights_title || "Empowering Relationship Insights for {sign} Moon").replace('{sign}', moonSignName)}</h4>
                  <div style="background: linear-gradient(145deg, #F0FDF4 0%, #FFFFFF 100%); border: 1px solid #BBF7D0; border-radius: 12px; padding: 16px; margin-bottom: 16px; color: #15803D; box-shadow: 0 2px 8px rgba(0,0,0,0.02); line-height: 1.6;">
                      <ul style="padding-left: 16px; margin: 0;">
                          <li>${compatibilityAdvice}</li>
                          ${d_txt.bh_insights_li2 || "<li>When choosing a partner, focus on someone who truly understands your core elemental needs, rather than just matching points blindly.</li>"}
                      </ul>
                  </div>
              `;

              let bhName = uiEx["Bhakoot Profile & Dosha Check"] || "Bhakoot Profile & Dosha Check";
              let badgeInfo = uiEx.lbl_info || "INFO";

