    setHtml("astroYoni", locYoni);
    setHtml("astroGan", locGan);
    setHtml("astroNadi", locNadi);
    setHtml("astroYunja", locYunja);
    setHtml("astroTatva", locTatva);
    setHtml("astroNameAlphabet", locNameAlphabet);
    setHtml("astroPaya", locPaya);

    // Populate Avakhada Chakra card
    setHtml("avakhadaVarna", locVarna);
    setHtml("avakhadaVashya", locVashya);
    setHtml("avakhadaYoni", locYoni);
    setHtml("avakhadaGana", locGan);
