        7: { day: "Thursday", month: "Magha", nakshatra: "Shatabhisha", moon: "Sagittarius", rashiM: "Gemini", rashiF: "Virgo", prahar: 4, yoga: "Shukla", karan: "Taitil", tithi: [4, 9, 14] },
        8: { day: "Friday", month: "Ashwin", nakshatra: "Revati", moon: "Taurus", rashiM: "Libra", rashiF: "Taurus", prahar: 1, yoga: "Vyatipata", karan: "Gara", tithi: [1, 6, 11] },
