    // Ghatak Rashi is the Bad Moon Sign (Ghatak Chandra), Ghatak Lagna is the Bad Ascendant
    setHtml("ghatakRashi", getLocalGhatakVal('rashis', gMoon));
    setHtml("ghatakLagna", getLocalGhatakVal('rashis', gRashi));

