    const uiExLoc = (localizedParagraphs[currentLang] && localizedParagraphs[currentLang].ui_extra) ? localizedParagraphs[currentLang].ui_extra : {};
    const lbl_gana_rev = uiExLoc.lbl_gana_rev || "Gana (Temperament):";
