      function reduceToSingleDigit(num) {
          let n = parseInt(num);
          if (isNaN(n) || n === 0) return 0;
          while (n > 9) {
              n = n.toString().split('').map(Number).reduce((a, b) => a + b, 0);
          }
          return n;
      }

      function calculateRadicalNumber(dobString) {
          const dateParts = dobString.includes('-') ? dobString.split('-') : [];
          if (dateParts.length !== 3) {
            const dateObj = new Date(dobString);
            if (!isNaN(dateObj)) {
               return reduceToSingleDigit(dateObj.getDate());
            }
            return 0;
          }

          let dayStr = "";
          if (dateParts[0].length === 4) {
              dayStr = dateParts[2];
          } else {
              dayStr = dateParts[0];
          }

          return reduceToSingleDigit(dayStr);
      }

      function calculateDestinyNumber(dobString) {
          let digitsOnly = dobString.replace(/[^0-9]/g, '');
          return reduceToSingleDigit(digitsOnly);
      }

      function calculateNameNumber(name, system = 'pythagorean') {
          const chaldeanMap = {
              A: 1, I: 1, J: 1, Q: 1, Y: 1,
              B: 2, K: 2, R: 2,
              C: 3, G: 3, L: 3, S: 3,
              D: 4, M: 4, T: 4,
              E: 5, H: 5, N: 5, X: 5,
              U: 6, V: 6, W: 6,
              O: 7, Z: 7,
              P: 8, F: 8
          };
          const pythagoreanMap = {
              A:1, J:1, S:1,
              B:2, K:2, T:2,
              C:3, L:3, U:3,
              D:4, M:4, V:4,
              E:5, N:5, W:5,
              F:6, O:6, X:6,
              G:7, P:7, Y:7,
              H:8, Q:8, Z:8,
              I:9, R:9
          };
          const activeMap = system === 'chaldean' ? chaldeanMap : pythagoreanMap;
          let total = 0;
          for (let char of name.toUpperCase()) {
              if (activeMap[char]) {
                  total += activeMap[char];
              }
          }
          return reduceToSingleDigit(total);
      }

      function reducePythagorean(num, keepMaster = false) {
          if (num === 0) return 0;
          while (num > 9 && !(keepMaster && (num === 11 || num === 22 || num === 33))) {
              let sum = 0, str = num.toString();
              for (let i = 0; i < str.length; i++) sum += parseInt(str[i]);
              num = sum;
          }
          return num;
      }

      function calculateAdvancedNumerology(name, dateStr, system = 'pythagorean') {
          const pythagoreanMap = { A:1, J:1, S:1, B:2, K:2, T:2, C:3, L:3, U:3, D:4, M:4, V:4, E:5, N:5, W:5, F:6, O:6, X:6, G:7, P:7, Y:7, H:8, Q:8, Z:8, I:9, R:9 };
          const chaldeanMap = { A:1, I:1, J:1, Q:1, Y:1, B:2, K:2, R:2, C:3, G:3, L:3, S:3, D:4, M:4, T:4, E:5, H:5, N:5, X:5, U:6, V:6, W:6, O:7, Z:7, F:8, P:8 };

          const activeMap = system === 'chaldean' ? chaldeanMap : pythagoreanMap;
          const vowels = ['A', 'E', 'I', 'O', 'U']; 

          let nameStr = name.toUpperCase().replace(/[^A-Z]/g, '');

          let expressionSum = 0;
          let soulSum = 0;
          let persSum = 0;
          let represented = new Set();

          for (let char of nameStr) {
              let val = activeMap[char] || 0;
              if (val > 0) {
                  expressionSum += val;
                  represented.add(val);
                  if (vowels.includes(char)) {
                      soulSum += val;
                  } else {
                      persSum += val;
                  }
              }
          }

          let keepMaster = system === 'pythagorean';
          let expression = reducePythagorean(expressionSum, keepMaster);
          let soulUrge = reducePythagorean(soulSum, keepMaster);
          let personality = reducePythagorean(persSum, keepMaster);
          let subconscious = represented.size;

          // Date parsing: accept YYYY-MM-DD or DD/MM/YYYY
          let dobParts = dateStr.split(/[-/.]/);
          let d = 0, m = 0, y = 0;
          if (dobParts.length === 3) {
              if (dobParts[0].length === 4) {
                  y = dobParts[0]; m = dobParts[1]; d = dobParts[2];
              } else {
                  d = dobParts[0]; m = dobParts[1]; y = dobParts[2];
              }
          }

          // Regular base sums for Life Path, using the base method (allowing master numbers per keepMaster = true)
          let daySum = reducePythagorean(parseInt(d));
          let monthSum = reducePythagorean(parseInt(m));
          let yearSum = reducePythagorean(parseInt(y));

          let lifePath = reducePythagorean(daySum + monthSum + yearSum, true);

          // Challenge sums MUST strictly reduce to 1-9 BEFORE subtraction, ignoring Master Numbers entirely
          let dayChallengeBase = reducePythagorean(parseInt(d), false);
          let monthChallengeBase = reducePythagorean(parseInt(m), false);
          let yearChallengeBase = reducePythagorean(parseInt(y), false);

          let c1 = Math.abs(monthChallengeBase - dayChallengeBase);
          let c2 = Math.abs(dayChallengeBase - yearChallengeBase);
          let c3 = Math.abs(c1 - c2);
          let c4 = Math.abs(monthChallengeBase - yearChallengeBase);

          // Life Period Cycles strictly require reducing but KEEPING Master Numbers (11, 22, 33)
          let periodMonth = reducePythagorean(parseInt(m), true);
          let periodDay = reducePythagorean(parseInt(d), true);
          let periodYear = reducePythagorean(parseInt(y), true);

          let ageKey = reduceToSingleDigit(parseInt(m) + parseInt(d));

          return {
              lifePath,
              personality,
              expression,
              soulUrge,
              subconscious,
              challenges: [c1, c2, c3, c4],
              birthYear: parseInt(y),
              reducedMonth: periodMonth, // Formative
              reducedDay: periodDay,     // Productive
              reducedYear: periodYear,   // Harvest
              ageKey: ageKey
          };
      }

