        let totalBavAs = BAV["Asc"].reduce((a, b) => a + b, 0);
        let totalBavSu = BAV["Sun"].reduce((a, b) => a + b, 0);
        let totalBavMo = BAV["Moon"].reduce((a, b) => a + b, 0);
